package incidencias.repositories;

import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.repository.CrudRepository;
import org.springframework.stereotype.Repository;

import incidencias.entities.Incidencia;

/**
 * Spring Data JPA repository for the {@link Incidencia} entity.
 *
 * <p>Provides basic CRUD operations inherited from {@link CrudRepository}
 * and custom query methods to retrieve incidents based on specific criteria.</p>
 *
 * <p>The implementation of this interface is automatically generated by Spring Data
 * based on the declared method signatures.</p>
 *
 * @author Daniel
 * @version 1.0
 */
@Repository
public interface IncidenciaRepository extends CrudRepository<Incidencia, Integer> {

    /**
     * Finds all incidents associated with a specific user, paginated.
     *
     * @param usuarioContexto user identifier
     * @param pageable pagination information
     * @return a paginated list of incidents for the given user
     */
    Page<Incidencia> findByUsuarioContexto(String usuarioContexto, Pageable pageable);

    /**
     * Finds all incidents associated with a specific class, paginated.
     *
     * @param clase class name
     * @param pageable pagination information
     * @return a paginated list of incidents for the given class
     */
    Page<Incidencia> findByClase(String clase, Pageable pageable);

    /**
     * Finds all incidents associated with a specific method, paginated.
     *
     * @param metodo method name
     * @param pageable pagination information
     * @return a paginated list of incidents for the given method
     */
    Page<Incidencia> findByMetodo(String metodo, Pageable pageable);

    /**
     * Checks if there are incidents associated with a specific user.
     *
     * @param usuarioContexto user identifier
     * @return {@code true} if incidents exist, {@code false} otherwise
     */
    boolean existsByUsuarioContexto(String usuarioContexto);

    /**
     * Checks if there are incidents associated with a specific class.
     *
     * @param clase class name
     * @return {@code true} if incidents exist, {@code false} otherwise
     */
    boolean existsByClase(String clase);

    /**
     * Checks if there are incidents associated with a specific method.
     *
     * @param metodo method name
     * @return {@code true} if incidents exist, {@code false} otherwise
     */
    boolean existsByMetodo(String metodo);

    /**
     * Retrieves all incidents with pagination support.
     *
     * @param pageable pagination information
     * @return a paginated list of incidents
     */
    Page<Incidencia> findAll(Pageable pageable);
}